17	package org.springframework.samples.petclinic.util;
18	
19	/**
20	 * Utility for computing the Luhn check digit over a string.
21	 */
22	public final class Luhn {
23	
24	    private Luhn() {
25	    }
26	
27	    /**
28	     * Compute the Luhn check digit (0-9) over the decimal digits contained in {@code value},
29	     * ignoring any non-digit characters.
30	     *
31	     * @param value the string whose digits form the payload
32	     * @return the single check digit that makes the payload plus digit a valid Luhn sequence
33	     */
34	    public static int checkDigit(String value) {
35	        int sum = 0;
36	        boolean doubleDigit = true;
37	        for (int i = value.length() - 1; i >= 0; i--) {
38	            char c = value.charAt(i);
39	            if (c < '0' || c > '9') {
40	                continue;
41	            }
42	            int digit = c - '0';
43	            if (doubleDigit) {
44	                digit *= 2;
45	                if (digit > 9) {
46	                    digit -= 9;
47	                }
48	            }
49	            sum += digit;
50	            doubleDigit = !doubleDigit;
51	        }
52	        return (10 - (sum % 10)) % 10;
53	    }
54	}
