22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ and 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "customer_code")
62	    private String customerCode;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "household_size")
71	    private Integer householdSize;
72	
73	    @Column(name = "bulk_signup_warning")
74	    private boolean bulkSignupWarning;
75	
76	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
77	    private Set<Pet> pets;
78	
79	    public String getAddress() {
80	        return this.address;
81	    }
82	
83	    public void setAddress(String address) {
84	        this.address = address;
85	    }
86	
87	    public String getCity() {
88	        return this.city;
89	    }
90	
91	    public void setCity(String city) {
92	        this.city = city;
93	    }
94	
95	    public String getTelephone() {
96	        return this.telephone;
97	    }
98	
99	    public void setTelephone(String telephone) {
100	        this.telephone = telephone;
101	    }
102	
103	    public String getEmail() {
104	        return this.email;
105	    }
106	
107	    /**
108	     * Stores the email in its canonical lower-cased form so it is always persisted and
109	     * returned lower-cased, regardless of the casing supplied by the client.
110	     */
111	    public void setEmail(String email) {
112	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
113	    }
114	
115	    public String getPostcode() {
116	        return this.postcode;
117	    }
118	
119	    public void setPostcode(String postcode) {
120	        this.postcode = postcode;
121	    }
122	
123	    public LocalDate getRegistrationDate() {
124	        return this.registrationDate;
125	    }
126	
127	    public void setRegistrationDate(LocalDate registrationDate) {
128	        this.registrationDate = registrationDate;
129	    }
130	
131	    public String getCustomerCode() {
132	        return this.customerCode;
133	    }
134	
135	    public void setCustomerCode(String customerCode) {
136	        this.customerCode = customerCode;
137	    }
138	
139	    public String getHouseholdId() {
140	        return this.householdId;
141	    }
142	
143	    public void setHouseholdId(String householdId) {
144	        this.householdId = householdId;
145	    }
146	
147	    public Integer getNamesakeCount() {
148	        return this.namesakeCount;
149	    }
150	
151	    public void setNamesakeCount(Integer namesakeCount) {
152	        this.namesakeCount = namesakeCount;
153	    }
154	
155	    public Integer getHouseholdSize() {
156	        return this.householdSize;
157	    }
158	
159	    public void setHouseholdSize(Integer householdSize) {
160	        this.householdSize = householdSize;
161	    }
162	
163	    public boolean isBulkSignupWarning() {
164	        return this.bulkSignupWarning;
165	    }
166	
167	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
168	        this.bulkSignupWarning = bulkSignupWarning;
169	    }
170	
171	    /**
172	     * The derived key that uniquely identifies an owner for duplicate detection: the normalized
173	     * telephone, the (lower-cased) email or the empty string when absent, and the household id or
174	     * the empty string when the owner belongs to no household, joined with {@code '|'}. Two owners
175	     * are duplicates only when their whole identity keys are equal, so members of the same household
176	     * with different telephones (or an owner reusing only a telephone or only an email) remain
177	     * distinct.
178	     */
179	    @Transient
180	    public String getIdentityKey() {
181	        return this.telephone + "|"
182	            + (this.email == null ? "" : this.email) + "|"
183	            + (this.householdId == null ? "" : this.householdId);
184	    }
185	
186	    /**
187	     * On first persist, default the registration date to the server's current date when the
188	     * client did not supply one, then roll the effective date forward so it always falls on a
189	     * business day (a weekend moves to the following Monday).
190	     */
191	    @PrePersist
192	    private void defaultRegistrationDate() {
193	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
194	        this.registrationDate = BusinessDay.rollForward(effectiveDate);
195	    }
196	
197	    protected Set<Pet> getPetsInternal() {
198	        if (this.pets == null) {
199	            this.pets = new HashSet<>();
200	        }
201	        return this.pets;
202	    }
203	
204	    protected void setPetsInternal(Set<Pet> pets) {
205	        this.pets = pets;
206	    }
207	
208	    public List<Pet> getPets() {
209	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
210	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
211	        return Collections.unmodifiableList(sortedPets);
212	    }
213	
214	    public void setPets(List<Pet> pets) {
215	        this.pets = new HashSet<>(pets);
216	    }
217	
218	    public void addPet(Pet pet) {
219	        getPetsInternal().add(pet);
220	        pet.setOwner(this);
221	    }
222	
223	    /**
224	     * Return the Pet with the given name, or null if none found for this Owner.
225	     *
226	     * @param name to test
227	     * @return true if pet name is already in use
228	     */
229	    public Pet getPet(String name) {
230	        return getPet(name, false);
231	    }
232	
233	    /**
234	     * Return the Pet with the given name, or null if none found for this Owner.
235	     *
236	     * @param name to test
237	     * @return true if pet name is already in use
238	     */
239	    public Pet getPet(String name, boolean ignoreNew) {
240	        name = name.toLowerCase();
241	        for (Pet pet : getPetsInternal()) {
242	            if (!ignoreNew || !pet.isNew()) {
243	                String compName = pet.getName();
244	                compName = compName.toLowerCase();
245	                if (compName.equals(name)) {
246	                    return pet;
247	                }
248	            }
249	        }
250	        return null;
251	    }
252	
253	    public Pet getPet(Integer petId) {
254	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
255	    }
256	
257	    @Override
258	    public String toString() {
259	        return new ToStringCreator(this)
260	
261	            .append("id", this.getId())
262	            .append("new", this.isNew())
263	            .append("lastName", this.getLastName())
264	            .append("firstName", this.getFirstName())
265	            .append("address", this.address)
266	            .append("city", this.city)
267	            .append("telephone", this.telephone)
268	            .append("email", this.email)
269	            .toString();
270	    }
271	}
