5	/**
6	 * Derives an owner's locality (canonical region), preferring the postcode over the city.
7	 *
8	 * <p>The postcode is looked up first via {@link PostcodeRule#regionForPostcode(String)}
9	 * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); the matching canonical
10	 * region string is returned. When the postcode is absent or in no known range, the city is looked
11	 * up in a small, fixed city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
12	 * {@code Brisbane -> QLD}). Any city not present in the table — including a {@code null} city —
13	 * derives the sentinel locality {@code "UNKNOWN"}. Preferring the postcode returns the same region
14	 * for known cities but disambiguates cities that share a name.
15	 */
16	public final class LocalityResolver {
17	
18	    /** Locality returned for any city not present in {@link #CITY_REGION}. */
19	    public static final String UNKNOWN = "UNKNOWN";
20	
21	    /** City -> canonical region; anything not listed derives {@link #UNKNOWN}. */
22	    private static final Map<String, String> CITY_REGION = Map.of(
23	        "Sydney", "NSW",
24	        "Melbourne", "VIC",
25	        "Brisbane", "QLD");
26	
27	    private LocalityResolver() {
28	    }
29	
30	    /**
31	     * Resolve the canonical region, preferring the postcode over the city.
32	     *
33	     * @param city     the owner's city, possibly {@code null}
34	     * @param postcode the owner's postcode, possibly {@code null}
35	     * @return the region whose range contains the postcode; otherwise the region derived from the
36	     *         city via {@link #resolve(String)} (which yields {@code "UNKNOWN"} for an unknown city)
37	     */
38	    public static String resolve(String city, String postcode) {
39	        String region = PostcodeRule.regionForPostcode(postcode);
40	        return region != null ? region : resolve(city);
41	    }
42	
43	    /**
44	     * Resolve the canonical region for a city alone.
45	     *
46	     * @param city the owner's city, possibly {@code null}
47	     * @return the canonical region string when the city is in the table, otherwise {@code "UNKNOWN"}
48	     */
49	    public static String resolve(String city) {
50	        return CITY_REGION.getOrDefault(city, UNKNOWN);
51	    }
52	}
