25	/**
26	 * Owns the notion of a "household" key and its stable identifier. A household groups owners
27	 * that share the same last name and address; this component canonicalizes those fields (so
28	 * values differing only in casing or spacing are treated as equal) and derives a stable,
29	 * shared {@code householdId} from them.
30	 *
31	 * <p>The id is deterministic: the same canonical household always maps to the same id,
32	 * independent of which member is registered first.
33	 */
34	@Component
35	public class HouseholdIdGenerator {
36	
37	    /**
38	     * Derive the stable household identifier for the given last name and address, formatted
39	     * {@code "HH-<12 upper-case hex>"} of the SHA-256 of the canonical household key.
40	     *
41	     * @param lastName the household's last name
42	     * @param address  the household's address
43	     * @return the stable, shared household id
44	     */
45	    public String generate(String lastName, String address) {
46	        String key = canonical(lastName) + "\n" + canonical(address);
47	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
48	    }
49	
50	    /**
51	     * Canonicalize a free-text field for household identity: trim, collapse internal runs of
52	     * whitespace to a single space and lower-case, so values differing only in casing or
53	     * spacing are treated as the same household.
54	     */
55	    public String canonical(String value) {
56	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
57	    }
58	
59	    private static String sha256Hex(String value) {
60	        try {
61	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
62	            StringBuilder sb = new StringBuilder(digest.length * 2);
63	            for (byte b : digest) {
64	                sb.append(String.format("%02x", b));
65	            }
66	            return sb.toString();
67	        } catch (NoSuchAlgorithmException e) {
68	            throw new IllegalStateException("SHA-256 not available", e);
69	        }
70	    }
71	}
